  async function loadConversations(){const s=state.conversations,epoch=++s.epoch;if(preview())s.rows=demoConversationRows();else{const [result,prefs]=await Promise.all([api(`/conversations?limit=100&include_closed=${s.filter==='archived'}`),api('/preferences').catch(()=>({pinned_sidebar_items:[]}))]);if(epoch!==s.epoch)return;window.uiPreferences={...(window.uiPreferences||{}),...prefs};const pins=Array.isArray(prefs.pinned_sidebar_items)?prefs.pinned_sidebar_items:[];s.rows=(Array.isArray(result.conversations)?result.conversations:[]).map(x=>({...x,pinned:pins.includes('chat:'+x.id)}))}if(!s.selected||!s.rows.some(x=>x.id===s.selected))s.selected=s.rows[0]?.id||null;render('conversations')}
